/**
 * Domain normalization and matching utilities.
 *
 * COPIED VERBATIM from `AI SDR/dashboard/lib/context/domain-utils.js`, which is
 * itself a port of `icp-dashboard/src/lib/domain-utils.ts` — the same functions
 * that produced `domain_aliases.root_name` / `.core_root` in the shared
 * database. Kept behaviourally identical on purpose: this dashboard groups the
 * same companies those rows describe, so any drift here silently disagrees with
 * the AI SDR app about who is who.
 *
 * Do not edit this file to fix a matching bug. Fix it in the AI SDR app and copy
 * it across, or the two frontends start reporting different company counts off
 * one database.
 *
 * NOTE: this exports its own `normalizeDomain` and `domainFromEmail`, which are
 * stricter than the ones in ./domains.js (they fold `docs.x.com` to `x.com` and
 * know two-part TLDs). ./domains.js still writes what the sync STORES; this file
 * is only used to decide which stored domains are the same company.
 *
 * Pure functions, zero dependencies.
 */

// Subdomains that should be stripped during normalization
const STRIP_PREFIXES = new Set([
  'www', 'docs', 'doc', 'blog', 'app', 'api', 'status', 'support',
  'help', 'dev', 'developer', 'developers', 'portal', 'dashboard',
  'console', 'admin', 'staging', 'demo', 'cdn', 'assets', 'static',
  'mail', 'm', 'mobile', 'go', 'get', 'try', 'info', 'about',
  'learn', 'community', 'forum', 'wiki', 'kb', 'knowledge',
  'cloud', 'platform', 'hub', 'store', 'shop', 'download',
  'downloads', 'release', 'releases', 'changelog', 'updates',
]);

// TLDs that are two-part (country code)
// Public suffixes: the part a company registers UNDER, never the company.
//
// `ac.in` was missing, so iima.ac.in and iitk.ac.in both reduced to the root
// "ac" — two unrelated institutions sharing an identity. That root also feeds
// the exclusion matcher, so excluding one .ac.in domain would have excluded
// every other one. The .in and .jp families are filled in for the same reason.
const TWO_PART_TLDS = new Set([
  'co.uk', 'co.in', 'co.jp', 'co.kr', 'co.nz', 'co.za', 'co.il', 'co.id', 'co.th',
  'com.au', 'com.br', 'com.cn', 'com.mx', 'com.sg', 'com.tr', 'com.hk', 'com.tw',
  'com.my', 'com.ph', 'com.vn', 'com.ua', 'com.pk', 'com.ar', 'com.co',
  'org.uk', 'net.au', 'ac.uk', 'gov.uk', 'edu.au',
  'ac.in', 'edu.in', 'org.in', 'net.in', 'gov.in', 'res.in', 'nic.in', 'firm.in',
  'ne.jp', 'or.jp', 'ac.jp', 'go.jp',
  'ac.nz', 'org.nz', 'govt.nz', 'ac.za', 'org.za', 'gov.au', 'edu.sg', 'gov.sg',
]);

// CDN / hosting domains that should NOT be treated as company domains
const HOSTING_DOMAINS = new Set([
  'netlify.app', 'vercel.app', 'herokuapp.com', 'github.io',
  'gitlab.io', 'pages.dev', 'fly.dev', 'railway.app',
  'render.com', 'onrender.com', 'surge.sh', 'now.sh',
  'firebaseapp.com', 'web.app', 'appspot.com',
  'azurewebsites.net', 'cloudfront.net', 'amazonaws.com',
]);

/**
 * Normalize a domain to its root form.
 *   "www.splunk.com"        → "splunk.com"
 *   "docs.splunk.com"       → "splunk.com"
 *   "http://www.splunk.com/en" → "splunk.com"
 */
export function normalizeDomain(input) {
  if (!input || typeof input !== 'string') return '';

  let domain = input.trim().toLowerCase();
  domain = domain.replace(/^https?:\/\//, '');
  domain = domain.split('/')[0].split('?')[0].split('#')[0];
  domain = domain.split(':')[0];
  domain = domain.replace(/\.+$/, '');

  if (!domain || !domain.includes('.')) return domain;

  // Hosting/CDN domain — the subdomain IS the identifier, keep as-is
  for (const hd of HOSTING_DOMAINS) {
    if (domain.endsWith('.' + hd) || domain === hd) return domain;
  }

  const parts = domain.split('.');

  // Two-part TLD (e.g. co.uk)
  if (parts.length >= 3) {
    const lastTwo = parts.slice(-2).join('.');
    if (TWO_PART_TLDS.has(lastTwo)) {
      if (parts.length >= 4) {
        const sub = parts.slice(0, -3).join('.');
        if (STRIP_PREFIXES.has(sub) || parts.length > 4) {
          return parts.slice(-3).join('.');
        }
      }
      return parts.slice(-3).join('.');
    }
  }

  // Standard domain: strip known prefixes
  if (parts.length >= 3) {
    const subdomain = parts[0];
    if (STRIP_PREFIXES.has(subdomain)) return parts.slice(1).join('.');
    if (parts.length > 3) return parts.slice(-2).join('.');
  }

  return domain;
}

/**
 * Extract the root name from a domain (without TLD).
 *   "splunk.com" → "splunk", "company.co.uk" → "company"
 */
export function extractRootName(domain) {
  const normalized = normalizeDomain(domain);
  if (!normalized) return '';

  const parts = normalized.split('.');
  const lastTwo = parts.slice(-2).join('.');

  // A hosting suffix is a public suffix too. HOSTING_DOMAINS already listed
  // vercel.app, but nothing consulted it here, so every customer site on
  // *.vercel.app reduced to "vercel" and was grouped with Vercel itself.
  // The label in front of the suffix is the tenant, not the platform.
  if (HOSTING_DOMAINS.has(lastTwo)) {
    return parts.length >= 3 ? parts[parts.length - 3] : '';
  }

  if (TWO_PART_TLDS.has(lastTwo)) {
    // A bare public suffix identifies nobody. Returning "ac" for "ac.in" is
    // how two unrelated universities ended up sharing a root.
    return parts.length >= 3 ? parts[parts.length - 3] : '';
  }

  if (parts.length >= 2) return parts[parts.length - 2];
  return parts[0];
}

// Companies register domains like trytruffle.ai, getpostman.com, usebraintrust.com.
// These prefixes are NOT subdomains — they're baked into the domain name itself.
const MARKETING_PREFIXES = [
  'try', 'get', 'use', 'go', 'my', 'hello', 'hey', 'meet',
  'with', 'join', 'run', 'start', 'build', 'make',
];

/**
 * Extract the "core" root by stripping marketing prefixes.
 *   "trytruffle.ai" → "truffle", "getpostman.com" → "postman"
 */
export function extractCoreRoot(domain) {
  const root = extractRootName(domain);
  if (!root || root.length < 4) return root;

  for (const prefix of MARKETING_PREFIXES) {
    if (root.startsWith(prefix) && root.length > prefix.length + 2) {
      const remainder = root.slice(prefix.length);
      if (remainder.length >= 3) return remainder;
    }
  }
  return root;
}

/**
 * Normalize a company name for comparison.
 *   "Vibrant Labs, Inc." → "vibrant labs"
 */
export function normalizeCompanyName(name) {
  if (!name || typeof name !== 'string') return '';

  let n = name.trim().toLowerCase();
  n = n.replace(/,?\s*(inc\.?|llc\.?|ltd\.?|corp\.?|co\.?|gmbh|s\.?a\.?|b\.?v\.?|plc|pty\.?\s*ltd\.?)$/i, '');
  n = n.replace(/[^a-z0-9\s]/g, '');
  n = n.replace(/\s+/g, ' ').trim();
  return n;
}

// Placeholder names that must NEVER be used as a matching key.
const JUNK_NAMES = new Set([
  'unknown', 'n a', 'na', 'none', 'null', 'nil', 'tbd', 'tba',
  'company', 'companies', 'test', 'sample', 'example', 'unnamed',
  'not found', 'not available', 'no name', 'undefined', 'blank', 'empty',
]);

/** True if a company name is a placeholder/junk value. */
export function isJunkName(name) {
  if (!name) return true;
  const n = normalizeCompanyName(name);
  if (!n || n.length < 3) return true;
  return JUNK_NAMES.has(n);
}

/** Check if two domains share the same root (docs.splunk.com ↔ splunk.com). */
export function sharesRoot(d1, d2) {
  if (!d1 || !d2) return false;

  const n1 = normalizeDomain(d1);
  const n2 = normalizeDomain(d2);
  if (n1 === n2) return true;

  const r1 = extractRootName(n1);
  const r2 = extractRootName(n2);
  if (!r1 || !r2 || r1.length < 3 || r2.length < 3) return false;
  if (r1 === r2) return true;

  // Fuzzy: one root contains the other ("datadoghq" ↔ "datadog")
  if (r1.length > 4 && r2.includes(r1)) return true;
  if (r2.length > 4 && r1.includes(r2)) return true;

  return false;
}

/**
 * STRICT root matching — only exactly identical roots.
 * Safe for automated decisions where false positives are unacceptable.
 *   isExactRootMatch("box.com", "dropbox.com") → false
 */
export function isExactRootMatch(d1, d2) {
  if (!d1 || !d2) return false;

  const n1 = normalizeDomain(d1);
  const n2 = normalizeDomain(d2);
  if (n1 === n2) return true;

  const r1 = extractRootName(n1);
  const r2 = extractRootName(n2);
  if (!r1 || !r2 || r1.length < 3 || r2.length < 3) return false;
  return r1 === r2;
}

/** Find the best matching domain from a list, or null. */
export function findMatchingDomain(input, existingDomains) {
  const normalized = normalizeDomain(input);
  const exact = existingDomains.find(d => normalizeDomain(d) === normalized);
  if (exact) return exact;
  const rootMatch = existingDomains.find(d => sharesRoot(d, input));
  if (rootMatch) return rootMatch;
  return null;
}

/** Clean a domain string from messy input formats. */
export function cleanDomainInput(input) {
  if (!input || typeof input !== 'string') return '';

  let cleaned = input.trim();
  cleaned = cleaned.replace(/^["']+|["']+$/g, '');
  cleaned = cleaned.replace(/^https?:\/\//i, '');
  cleaned = cleaned.replace(/^www\./i, '');
  cleaned = cleaned.split('/')[0];
  cleaned = cleaned.split(':')[0];
  return cleaned.toLowerCase().trim();
}

// ── Additions for the Context Archiver ──────────────────────────────────────

/**
 * Free/personal email providers. Without this list, every gmail.com address
 * resolves to a "company" called Gmail and poisons the entire archive.
 */
export const FREEMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com',
  'msn.com', 'yahoo.com', 'yahoo.co.uk', 'yahoo.co.in', 'ymail.com',
  'rocketmail.com', 'aol.com', 'icloud.com', 'me.com', 'mac.com',
  'proton.me', 'protonmail.com', 'pm.me', 'tutanota.com', 'zoho.com',
  'gmx.com', 'gmx.de', 'gmx.net', 'mail.com', 'mail.ru', 'yandex.ru',
  'yandex.com', 'qq.com', '163.com', '126.com', 'naver.com', 'daum.net',
  'fastmail.com', 'hey.com', 'hushmail.com', 'inbox.com', 'rediffmail.com',
  'comcast.net', 'verizon.net', 'att.net', 'sbcglobal.net', 'cox.net',
  'btinternet.com', 'orange.fr', 'free.fr', 'web.de', 't-online.de',
  'example.com', 'test.com', 'localhost',
]);

/** True if this is a personal/free mail domain, not a company domain. */
export function isFreemail(domain) {
  if (!domain) return true;
  return FREEMAIL_DOMAINS.has(normalizeDomain(domain));
}

/**
 * Detect domain values that are corruption artifacts rather than real domains.
 *
 * This is not hypothetical: 1,963 rows in `reachout_history` carry the literal
 * string "[object object]" — a JS object stringified instead of its .domain
 * property by whatever wrote that table. Archiving those as accounts would
 * create a phantom company holding 19,310 emails.
 */
const CORRUPT_DOMAIN_PATTERNS = [
  /^\[object\s+\w+\]$/i,   // "[object Object]"
  /^undefined$/i,
  /^null$/i,
  /^nan$/i,
  /^n\/?a$/i,
  /^-+$/,
];

export function isCorruptDomain(domain) {
  if (!domain || typeof domain !== 'string') return true;
  const d = domain.trim().toLowerCase();
  if (!d) return true;
  if (CORRUPT_DOMAIN_PATTERNS.some(re => re.test(d))) return true;
  // A real domain has a dot and no whitespace.
  if (!d.includes('.') || /\s/.test(d)) return true;
  return false;
}

/** Extract and normalize the domain from an email address, or '' if freemail. */
export function domainFromEmail(email) {
  if (!email || typeof email !== 'string' || !email.includes('@')) return '';
  const raw = email.trim().toLowerCase().split('@').pop();
  if (!raw) return '';
  const normalized = normalizeDomain(raw);
  return isFreemail(normalized) ? '' : normalized;
}

/**
 * Pull candidate domains out of free text (URLs or bare domains).
 * Used by Tier 2 resolution on Slack messages and meeting notes.
 */
const DOMAIN_IN_TEXT = /\b((?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,})\b/gi;
const IGNORED_TEXT_DOMAINS = new Set([
  'slack.com', 'notion.so', 'google.com', 'docs.google.com', 'github.com',
  'linkedin.com', 'zoom.us', 'fireflies.ai', 'hubspot.com', 'instantly.ai',
  'calendly.com', 'youtube.com', 'twitter.com', 'x.com', 'medium.com',
  'reo.dev',
]);

export function extractDomainsFromText(text, { limit = 10 } = {}) {
  if (!text || typeof text !== 'string') return [];
  const found = new Set();

  for (const match of text.matchAll(DOMAIN_IN_TEXT)) {
    const candidate = normalizeDomain(match[1]);
    if (!candidate || !candidate.includes('.')) continue;
    if (IGNORED_TEXT_DOMAINS.has(candidate)) continue;
    if (isFreemail(candidate)) continue;
    // A bare word with a 2-letter TLD is usually a sentence artifact ("e.g")
    if (candidate.length < 5) continue;
    found.add(candidate);
    if (found.size >= limit) break;
  }

  return Array.from(found);
}

// ── Matching a domain against a known set ───────────────────────────────────

/**
 * Company roots that are ordinary words. Matching these against anything
 * produces pure noise — observed live: "palette.team" matched a company whose
 * root is "team", and "landh.tech" matched one whose root is "tech".
 *
 * Only ever a guard on the FUZZY tiers. An exact domain, an explicit domain
 * (resolver Tier 2) or an email address (Tier 1) still resolves them, so a real
 * mention of team.gg is never lost.
 */
export const GENERIC_ROOTS = new Set([
  'team', 'tech', 'white', 'data', 'cloud', 'code', 'dev', 'devs', 'apps',
  'web', 'site', 'page', 'post', 'link', 'mail', 'home', 'work', 'life',
  'world', 'group', 'global', 'digital', 'systems', 'solutions', 'software',
  'labs', 'studio', 'agency', 'media', 'network', 'service', 'services',
  'platform', 'product', 'project', 'design', 'build', 'start', 'launch',
  'growth', 'sales', 'market', 'brand', 'store', 'shop', 'money', 'bank',
  'health', 'care', 'learn', 'school', 'book', 'news', 'blog', 'chat', 'talk',
  'meet', 'call', 'share', 'view', 'list', 'find', 'search', 'help', 'support',
  'admin', 'test', 'demo', 'beta', 'alpha', 'main', 'core', 'base', 'hub',
  'first', 'next', 'best', 'good', 'great', 'real', 'true', 'open', 'free',
  'fast', 'easy', 'smart', 'plus', 'micro', 'nano', 'ultra', 'super',
  'space', 'time', 'point', 'line', 'flow', 'wave', 'edge', 'peak', 'rise',
  'info', 'file', 'files', 'user', 'users', 'client', 'server', 'stack',
  'email', 'inbox', 'reply', 'review', 'update', 'report', 'notes', 'draft',
  'source', 'target', 'signal', 'signals', 'intent', 'lead', 'leads', 'deal',
  'account', 'company', 'contact', 'sales', 'stage', 'pipeline', 'when',
  // Three-letter words, now that the floor is 3 chars. TLD artifacts (com,
  // org, net…) are additionally caught by the ambiguity heuristic.
  'com', 'org', 'net', 'edu', 'gov', 'inc', 'llc', 'ltd', 'the', 'and', 'for',
  'you', 'our', 'his', 'her', 'was', 'are', 'has', 'had', 'not', 'but', 'all',
  'can', 'day', 'get', 'got', 'how', 'its', 'let', 'may', 'new', 'now', 'one',
  'out', 'own', 'say', 'see', 'she', 'too', 'two', 'use', 'via', 'who', 'why',
  'yes', 'yet', 'top', 'end', 'run', 'set', 'add', 'ask', 'try', 'buy', 'pay',
  'call', 'week', 'call', 'this', 'that', 'with', 'from', 'have', 'they',
  'been', 'were', 'will', 'more', 'than', 'them', 'some', 'what', 'just',
  'like', 'also', 'into', 'over', 'back', 'down', 'only', 'very', 'good',
]);

/**
 * The forms of a domain that identify the COMPANY rather than the registration.
 *
 * `joined` is the one that is not obvious. A company whose brand runs across
 * the label and the TLD — linx.security, grip.security, oxide.computer — has a
 * root of "linx", so it matches neither linxsecurity.io (root "linxsecurity")
 * nor itself under a different TLD. Dropping the dot puts the two sides in the
 * same alphabet. Measured over the 27,259 rows of `companies`, this form links
 * 70 pairs, and all but a handful are the same company twice.
 */
export function domainForms(input) {
  const normalized = normalizeDomain(input);
  if (!normalized || isCorruptDomain(normalized)) return null;

  const labels = normalized.split('.');
  // ".com" and "foo..com" are junk rows, and their empty label makes every
  // other domain on that TLD look like a match. One of them is in `companies`.
  if (labels.length < 2 || labels.some(l => !l)) return null;

  return {
    normalized,
    root:     extractRootName(normalized),
    coreRoot: extractCoreRoot(normalized),
    joined:   labels.join(''),
  };
}

/** A key only counts if it is long enough to be a brand and is not a word. */
const usableKey = (key, min) => Boolean(key) && key.length >= min && !GENERIC_ROOTS.has(key);

/**
 * Words a company bolts onto its own brand on a second domain, or drops when
 * it rebrands. Abnormal Security became Abnormal AI and kept both mailboxes
 * alive, so an Apollo export carries @abnormalsecurity.com addresses for an
 * account added as abnormal.ai — same company, no form in common.
 *
 * Only ever consulted as the REMAINDER of a containment, never as a key.
 */
const BRAND_SUFFIXES = new Set([
  'security', 'labs', 'lab', 'hq', 'technologies', 'technology', 'software',
  'soft', 'systems', 'data', 'cloud', 'computing', 'computer', 'networks',
  'analytics', 'robotics', 'health', 'digital', 'studio', 'works', 'group',
  'global', 'platform', 'solutions', 'corp', 'inc',
]);

/**
 * One root is the other plus a descriptor, APPENDED:
 *   "abnormal" ↔ "abnormalsecurity"      "redis" ↔ "redislabs"
 *
 * Containment alone is not evidence — "box" sits inside "dropbox" — so three
 * things are required beyond it. The anchor must be long enough to be a brand
 * on its own (5, the same floor `core` uses). The remainder must be a word
 * companies actually append. And it must be APPENDED, never prepended: a
 * descriptor in front makes a different company far more often than not, and
 * measuring it over all 27,259 rows of `companies` is what settled it —
 * dropping the prepended branch removed devcycle.com↔cycle.io,
 * cloudfactory.com↔factory.ai, databricks.com↔bricks.sh, netbrain.com↔brain.bzh
 * and six more like them, and cost nothing real, because a brand extension
 * reads "Walmart Labs", not "Labs Walmart".
 *
 * The short descriptors are left out for the same reason: "ai" linked
 * guardrails.io to Guardrails AI and archetype.dev to Archetype AI, which are
 * four different companies, and "sec" linked crowd.dev to CrowdSec.
 */
function brandSuffixMatch(r1, r2) {
  if (!r1 || !r2 || r1 === r2) return false;
  const [short, long] = r1.length < r2.length ? [r1, r2] : [r2, r1];
  if (!usableKey(short, 5) || !long.startsWith(short)) return false;
  return BRAND_SUFFIXES.has(long.slice(short.length));
}

/**
 * How two domains relate, strongest tier first, or null.
 *
 *   exact  splunk.com        ↔ www.splunk.com
 *   root   splunk.com        ↔ splunk.io          (same label, different TLD)
 *   brand  linx.security     ↔ linxsecurity.io    (brand split across the TLD)
 *   core   getpostman.com    ↔ postman.com        (marketing prefix)
 *   suffix abnormal.ai       ↔ abnormalsecurity.com (brand + descriptor)
 *
 * Accepts either a domain string or the result of domainForms(), so a caller
 * comparing one input against many candidates can prepare the forms once.
 */
export function domainMatchMethod(a, b) {
  const A = typeof a === 'string' ? domainForms(a) : a;
  const B = typeof b === 'string' ? domainForms(b) : b;
  if (!A || !B) return null;

  if (A.normalized === B.normalized) return 'exact';
  if (A.root === B.root && usableKey(A.root, 3)) return 'root';
  if (A.joined === B.root && usableKey(A.joined, 5)) return 'brand';
  if (B.joined === A.root && usableKey(B.joined, 5)) return 'brand';
  // 5, not 4: stripping "use" off usegit.ai leaves "git", which matched an
  // unrelated Gitai. A core root that short is not evidence of anything.
  if (A.coreRoot === B.coreRoot && usableKey(A.coreRoot, 5)) return 'core';
  if (brandSuffixMatch(A.root, B.root)) return 'suffix';

  return null;
}

const METHOD_RANK = { exact: 0, root: 1, brand: 2, core: 3, suffix: 4 };

/**
 * A matcher over a fixed set of known domains — the accounts in a campaign, the
 * rows of `companies`, whatever the caller has.
 *
 * Returns { match, method, ambiguous }. Two rules make this safe to act on:
 *
 *  - The best tier wins outright. An exact hit is never displaced by a fuzzy
 *    one, so adding fuzzy tiers cannot change an answer that was already right.
 *  - A tie inside a fuzzy tier is REFUSED, not guessed: `linx` alone matches
 *    both linx.security and linx.software, and picking one of those at random
 *    is how contacts end up filed under the wrong company. `ambiguous` names
 *    the candidates so the caller can say which.
 */
export function domainMatcher(candidates, toDomain = (c) => c) {
  const prepared = [];
  for (const candidate of candidates) {
    const forms = domainForms(toDomain(candidate));
    if (forms) prepared.push({ candidate, forms });
  }

  return function match(input) {
    const forms = domainForms(input);
    if (!forms) return { match: null, method: null, ambiguous: [] };

    let bestRank = Infinity, bestMethod = null, hits = [];
    for (const { candidate, forms: other } of prepared) {
      const method = domainMatchMethod(forms, other);
      if (!method) continue;
      const rank = METHOD_RANK[method];
      if (rank < bestRank) { bestRank = rank; bestMethod = method; hits = [candidate]; }
      else if (rank === bestRank && !hits.includes(candidate)) hits.push(candidate);
    }

    if (!hits.length) return { match: null, method: null, ambiguous: [] };
    if (hits.length > 1) return { match: null, method: null, ambiguous: hits };
    return { match: hits[0], method: bestMethod, ambiguous: [] };
  };
}
